import{_ as t,c as a,o as s,a3 as r}from"./chunks/framework.Dokpd4od.js";const p=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"master/Introduction.md","filePath":"master/Introduction.md","lastUpdated":1792041590000}'),n={name:"master/Introduction.md"};function o(i,e,l,h,d,c){return s(),a("div",null,e[0]||(e[0]=[r(`<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>Aureus ERP is open-source business software. It keeps sales, purchasing, stock, production, accounting, people and your website in one system. Every module reads the same records, so you enter data once and use it everywhere.</p><p>This guide teaches you how to use Aureus ERP, one task at a time. Each page explains a feature, shows the exact steps and points you to the next page.</p><blockquote><p><strong>In simple words:</strong> One system for your whole business, and one guide to learn it.</p></blockquote><h2 id="how-the-modules-work-together" tabindex="-1">How the modules work together <a class="header-anchor" href="#how-the-modules-work-together" aria-label="Permalink to &quot;How the modules work together&quot;">​</a></h2><p>Modules share contacts, products and documents. A sale can start a delivery. A delivery can start an invoice. A purchase can fill your stock.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Sales order ──► Delivery (Inventory) ──► Customer invoice (Finance)</span></span>
<span class="line"><span>Purchase order ──► Receipt (Inventory) ──► Vendor bill (Finance)</span></span>
<span class="line"><span>Manufacturing order ──► Finished goods (Inventory)</span></span></code></pre></div><p>You do not need every module. Install the ones you need and add others later.</p><h2 id="where-to-start" tabindex="-1">Where to start <a class="header-anchor" href="#where-to-start" aria-label="Permalink to &quot;Where to start&quot;">​</a></h2><p>Pick the line that matches your job.</p><table tabindex="0"><thead><tr><th>If you want to</th><th>Start here</th></tr></thead><tbody><tr><td>Learn the basics every screen shares</td><td><a href="./getting-started/stages.html">Getting started</a></td></tr><tr><td>Add users, companies and options</td><td><a href="./general-settings/">General settings</a></td></tr><tr><td>Quote, sell and invoice</td><td><a href="./sales/sales/">Sales</a></td></tr><tr><td>Buy from vendors</td><td><a href="./supply-chain/purchase/">Purchase</a></td></tr><tr><td>Track and move stock</td><td><a href="./supply-chain/inventories/">Inventory</a></td></tr><tr><td>Build products from components</td><td><a href="./supply-chain/manufacturing/">Manufacturing</a></td></tr><tr><td>Bill customers and pay vendors</td><td><a href="./finance/">Finance</a></td></tr><tr><td>Manage people and leave</td><td><a href="./human-resources/employees/">Employees</a></td></tr><tr><td>Run projects and log hours</td><td><a href="./services/project/">Project</a></td></tr><tr><td>Publish a public site and blog</td><td><a href="./website/">Website</a></td></tr></tbody></table><h2 id="what-is-in-the-guide" tabindex="-1">What is in the guide <a class="header-anchor" href="#what-is-in-the-guide" aria-label="Permalink to &quot;What is in the guide&quot;">​</a></h2><p>The sidebar groups the guide the same way Aureus ERP groups its modules.</p><h3 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h3><p>Short pages on ideas that appear in every module.</p><ul><li><a href="./getting-started/stages.html">Stages</a>: move records through steps.</li><li><a href="./getting-started/chatter.html">Chatter</a>: write notes and follow a record.</li><li><a href="./getting-started/activities.html">Activities</a>: schedule and track to-dos.</li><li><a href="./getting-started/search-filter-group.html">Search, filter and group</a>: find records fast.</li><li><a href="./getting-started/contacts/contacts.html">Contacts</a>: the customers, vendors and companies all modules share.</li></ul><h3 id="general-settings" tabindex="-1">General settings <a class="header-anchor" href="#general-settings" aria-label="Permalink to &quot;General settings&quot;">​</a></h3><ul><li><a href="./general-settings/">General settings</a>: users, roles, companies, teams, sequences and system-wide options.</li></ul><h3 id="finance" tabindex="-1">Finance <a class="header-anchor" href="#finance" aria-label="Permalink to &quot;Finance&quot;">​</a></h3><ul><li><a href="./finance/">Finance</a>: invoices, bills, payments, taxes and reports.</li></ul><h3 id="sales" tabindex="-1">Sales <a class="header-anchor" href="#sales" aria-label="Permalink to &quot;Sales&quot;">​</a></h3><ul><li><a href="./sales/sales/">Sales</a>: quotations, orders, products and prices.</li><li><a href="./sales/point-of-sale/">Point of Sale</a>: the cash register for shops and cafés.</li></ul><h3 id="supply-chain" tabindex="-1">Supply chain <a class="header-anchor" href="#supply-chain" aria-label="Permalink to &quot;Supply chain&quot;">​</a></h3><ul><li><a href="./supply-chain/purchase/">Purchase</a>: requests for quotation, orders, receipts and vendor bills.</li><li><a href="./supply-chain/inventories/">Inventory</a>: warehouses, transfers, counts and tracking.</li><li><a href="./supply-chain/manufacturing/">Manufacturing</a>: bills of materials, work centers and manufacturing orders.</li><li><a href="./supply-chain/maintenance/">Maintenance</a>: equipment and repair requests.</li></ul><h3 id="human-resources" tabindex="-1">Human resources <a class="header-anchor" href="#human-resources" aria-label="Permalink to &quot;Human resources&quot;">​</a></h3><ul><li><a href="./human-resources/employees/">Employees</a>: the people directory.</li><li><a href="./human-resources/recruitment/">Recruitment</a>: applications and hiring setup.</li><li><a href="./human-resources/time-off/">Time off</a>: leave requests, approvals and balances.</li></ul><h3 id="services" tabindex="-1">Services <a class="header-anchor" href="#services" aria-label="Permalink to &quot;Services&quot;">​</a></h3><ul><li><a href="./services/project/">Project</a>: projects, tasks and progress.</li><li><a href="./services/timesheets/">Timesheets</a>: hours spent on tasks.</li></ul><h3 id="website" tabindex="-1">Website <a class="header-anchor" href="#website" aria-label="Permalink to &quot;Website&quot;">​</a></h3><ul><li><a href="./website/">Website</a>: pages, blog, customer accounts and contact details.</li></ul><h2 id="how-each-page-is-built" tabindex="-1">How each page is built <a class="header-anchor" href="#how-each-page-is-built" aria-label="Permalink to &quot;How each page is built&quot;">​</a></h2><p>Most pages follow the same pattern, so you always know where to look.</p><ul><li>A short introduction and an <strong>In simple words</strong> line explain the feature.</li><li><strong>Settings</strong> tells you which option must be on before a menu appears.</li><li>Numbered steps walk you through the screen, with a screenshot for each step.</li><li>Menu paths look like <code>Module → Section → Page</code>.</li><li>Field names are in <strong>bold italics</strong>, and buttons are in <strong>bold</strong>.</li><li><strong>See also</strong> at the end links to related pages.</li></ul><p>Click any screenshot to enlarge it.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Use the search box at the top of this site to jump straight to a feature, a field name or a button.</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>You only see the menus your role allows. If a menu in this guide is missing on your screen, ask an administrator to check your role and installed plugins.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./general-settings/">General settings</a></li><li><a href="./getting-started/search-filter-group.html">Search, filter and group</a></li><li><a href="./getting-started/contacts/contacts.html">Contacts</a></li></ul>`,38)]))}const g=t(n,[["render",o]]);export{p as __pageData,g as default};
